package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.util.regex.*;import java.io.*;
/** Explicit user teaching and external evidence, retrieved as attributed text; never executable instructions. */
final class KnowledgeNotebook{
 static final int MAX=128,TEXT=262144,BUDGET=4000000;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-knowledge-notebook",0);}
 static JSONArray data(Context c)throws Exception{return NotebookDisk.of(c).legacyRows();}
 static void validate(JSONArray rows)throws Exception{if(rows.length()>MAX||rows.toString().length()>BUDGET)throw new IllegalArgumentException("Cuaderno demasiado grande");Set<String> ids=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);RuntimeProgram.keys(r,"id","title","text","source","origin","saved","truncated");if(!r.getString("id").matches("[a-f0-9]{64}")||!ids.add(r.getString("id"))||r.getString("title").length()>160||r.getString("text").trim().isEmpty()||r.getString("text").length()>TEXT||r.getString("source").length()>2000||!r.getString("origin").matches("user|web")||r.getLong("saved")<0)throw new IllegalArgumentException("Entrada inválida");r.getBoolean("truncated");if(r.getString("origin").equals("web")&&!r.getString("source").startsWith("https://"))throw new IllegalArgumentException("Fuente web sin HTTPS");}}
 static JSONObject entry(String title,String text,String source,String origin,long time)throws Exception{if(text.trim().isEmpty())throw new IllegalArgumentException("No recibí contenido para guardar");boolean clipped=text.length()>TEXT;String limited=text.substring(0,Math.min(text.length(),TEXT));String heading=title.trim();if(heading.isEmpty())heading=limited.substring(0,Math.min(80,limited.length()));heading=heading.substring(0,Math.min(160,heading.length()));String id=JavaMethodEditor.hash(origin+"|"+(origin.equals("web")?source:limited));return new JSONObject().put("id",id).put("title",heading).put("text",limited).put("source",source).put("origin",origin).put("saved",time).put("truncated",clipped);}
 static JSONArray merge(JSONArray old,JSONObject item)throws Exception{JSONArray next=new JSONArray();next.put(item);for(int i=0;i<old.length();i++)if(!old.getJSONObject(i).getString("id").equals(item.getString("id")))next.put(old.getJSONObject(i));validate(next);return next;}
 static String remember(Context c,String title,String text,String source,String origin)throws Exception{return rememberReader(c,title,new StringReader(text),source,origin);}
 static String rememberReader(Context c,String title,Reader text,String source,String origin)throws Exception{String saved=NotebookDisk.of(c).put(title,text,source,origin);try{return saved+"\n"+ReadingTraining.afterLearning(c);}catch(Exception e){return saved+"\nDocumento conservado; entrenamiento pendiente: "+AndroidRepair.summary(e);}}
 static void restore(Context c,JSONArray rows)throws Exception{NotebookDisk.of(c).restoreLegacy(rows);}
 static String[] chunks(String text){List<String> out=new ArrayList<>();for(String part:text.split("(?<=[.!?])\\s+|[\\r\\n]+")){String p=part.trim();while(p.length()>700){int end=p.lastIndexOf(' ',700);if(end<150)end=700;out.add(p.substring(0,end));p=p.substring(end).trim();}if(!p.isEmpty())out.add(p);}return out.toArray(new String[0]);}
 static String retrieve(JSONArray rows,String query)throws Exception{return ReadingKnowledge.answer(rows,query);}
 static String reply(Context c,String raw)throws Exception{String input=FollowUp.resolve(c,raw);String answer=answer(c,input);if(answer!=null){FollowUp.remember(c,input,null);if(!input.equals(FollowUp.strip(raw)))answer="(Entendí que seguís hablando de «"+input.substring(Math.min(input.length(),FollowUp.strip(raw).replaceAll("[?¿!¡.]+\\s*$","").trim().length())).trim()+"».)\n"+answer;}return answer;}
 static String answer(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);if(!ReadingKnowledge.informative(input))return null;String chained=LectorChain.reply(c,input);if(chained!=null)return chained;JSONArray rows=NotebookDisk.of(c).selected(input);String result=retrieve(rows,input);if(result==null){String neural=Lector.reply(c,rows,input);if(neural!=null)return neural;}else if(Lector.SELECTOR){String sure=Lector.confident(c,rows,input,result);if(sure!=null)result=sure+"\n\n"+result;}if(result==null)result=ReadingKnowledge.missing(rows,input);if(result!=null)result=ReadingKnowledge.style(result,MobileCore.prefs(c).getString("style","normal"),rows,input);if(result==null&&q.matches("(?s).*(?:pagina|enlace|lo que aprendiste|lo que guardaste).*"))return "No encontré un fragmento suficientemente relacionado en el cuaderno. Decime el tema de la fuente o pasame el enlace.";return result;}
 static final class Intent{String kind="",text="",url="";boolean crawl;Intent(String k,String t){kind=k;text=t;}}
 static boolean teachingMessage(String text){if(text.length()>TEXT+64)return false;try{Intent p=parse(text);return p!=null&&p.kind.equals("teach")&&p.text.length()<=TEXT;}catch(Exception e){return false;}}
 static Intent parse(String raw){String clean=NaturalCoding.polite(raw).trim(),q=ChatLanguage.normalize(clean);String crawling=PageCrawl.preference(clean);if(crawling!=null)return new Intent("crawl_"+crawling,"");if(q.startsWith("no "))return null;if(PageCrawl.followUp(clean))return new Intent("crawl_last",clean);if(q.startsWith("recorda que ")||q.startsWith("recuerda que "))return null;if(q.startsWith("aprende esta respuesta")||q.startsWith("aprende esta variante"))return null;
  if(q.matches("(?:estado|como va|informe|progreso) (?:del |el )?lector(?: neuronal)?|que aprendio (?:el|tu) lector|mostrame (?:el|tu) lector(?: neuronal)?"))return new Intent("reader_status","");if(q.matches("(?:esa|esta|la) respuesta (?:estuvo|esta|fue) (?:muy )?bien|bien respondido|respondiste bien|esa estuvo bien|buena respuesta"))return new Intent("real_good","");if(q.matches("(?:esa|esta|la) respuesta (?:estuvo|esta|fue) (?:muy )?mal|mal respondido|respondiste mal|esa estuvo mal|mala respuesta"))return new Intent("real_bad","");if(q.matches("ajustate(?: sola)?(?: con mis (?:preguntas|respuestas))?|ajusta tu (?:seguridad|umbral)|calibrate(?: con mis preguntas)?"))return new Intent("self_tune","");if(q.matches("(?:volve|vuelve|regresa) a los valores de fabrica|valores de fabrica|deshace (?:el|tu) ajuste"))return new Intent("self_reset","");if(q.matches("examen con mis preguntas|(?:tomate|toma|hace) (?:el |un )?examen con mis preguntas|como te va con mis preguntas|mis preguntas reales"))return new Intent("real_exam","");if(q.matches("(?:tomate|toma|hace|haz|rendi) un examen|examen del lector|ponete a prueba|examinate"))return new Intent("reader_exam","");if(q.matches("(?:hace|haz|corre|ejecuta) (?:una |la )?autoprueba|autoprueba|proba que todo funcione|revisa que todo funcione"))return new Intent("self_check","");if(q.matches("(?:hace|haz) crecer (?:el|tu) lector|agrega(?:le)? una capa al lector|suma(?:le)? (?:una capa|parametros) al lector|agranda (?:el|tu) lector"))return new Intent("reader_grow","");
  if(q.matches("(?:estado|espacio|lugar|tamano) (?:de|en) (?:la|tu|mi) biblioteca|cuanto (?:lugar|espacio) (?:queda|hay) en (?:la|tu) biblioteca|(?:hace|haz|libera|liberar) (?:lugar|espacio) en (?:la|tu) biblioteca"))return new Intent("library_room","");Matcher trim=Pattern.compile("(?:borra|olvida|elimina|saca) las ([0-9]{1,4}) (?:paginas|lecturas|fuentes)(?: web| de la web| de internet)? mas (?:viejas|antiguas)").matcher(q);if(trim.matches())return new Intent("library_trim",trim.group(1));if(q.matches("(?:(?:busca|mostrame|hay|detecta|revisa) )?(?:las )?contradicciones(?: (?:en|entre) (?:mis|tus|las) (?:fuentes|lecturas))?|que fuentes se contradicen"))return new Intent("conflicts","");
  if(q.matches("aprende de un archivo|lee un archivo|importa un texto|importa un archivo de texto|aprende un archivo de texto"))return new Intent("file","");
  if(q.matches("respalda mi conocimiento|respalda mis conocimientos|exporta mis conocimientos|exporta mi conocimiento|respalda mi memoria|guarda un respaldo del conocimiento|guarda todo lo que aprendiste"))return new Intent("export","");
  if(q.matches("restaura mis conocimientos|importa mis conocimientos|recupera mi memoria|restaura mi conocimiento"))return new Intent("import","");
  if(q.matches("que palabras aprendiste|mi vocabulario|tu vocabulario aprendido|que vocabulario aprendiste|mostrame tu vocabulario"))return new Intent("vocabulary","");
  if(q.matches("resumilo|resumelo|resumi la pagina|que dice ese enlace|que aprendiste de ese enlace|que recordas de esa pagina"))return new Intent("last","");if(q.matches("que aprendiste|que conocimientos guardaste|mostrame lo que aprendiste|mis conocimientos|que sabes de lo que te ensene"))return new Intent("status","");if(q.matches("borra todos los conocimientos guardados|olvida todos los conocimientos guardados"))return new Intent("clear","");if(q.matches("(?:hacete|hazte|volvete|vuelvete) mas inteligente|mejora tu inteligencia"))return new Intent("coach","");
  String link=PageLinks.extract(clean);if(link!=null){Intent intent=new Intent("web",clean);intent.url=link;intent.crawl=PageCrawl.wanted(clean);return intent;}
  Matcher topic=Pattern.compile("(?isu)^(?:aprende|aprendé|aprendas|aprender) (?:sobre|acerca de) (.{2,100})[.! ]*$").matcher(clean);if(topic.matches())return new Intent("topic",topic.group(1).trim());
  Matcher teach=Pattern.compile("(?isu)^(?:aprende|aprendé|aprendas)(?: (?:que|esto|lo siguiente))?\\s*[: ]\\s*(.+)$|^(?:recorda|recordá|recuerda|recuerdes|guarda|guardá|guardes) (?:que|esto|lo siguiente)\\s*[: ]?\\s*(.+)$").matcher(clean);if(teach.matches()){String content=teach.group(1)!=null?teach.group(1).trim():teach.group(2).trim();String normalized=ChatLanguage.normalize(content);if(normalized.matches("esto|eso|lo siguiente|lo anterior"))throw new IllegalArgumentException("Pasame el contenido o el enlace que querés que aprenda; no guardé una palabra sin información.");if(q.startsWith("aprende ")&&!q.startsWith("aprende que ")&&!q.startsWith("aprende esto")&&!clean.contains(":")&&normalized.split(" ").length<=5&&!normalized.matches("(?s).*\\b(?:es|son|tiene|usa|llama|significa)\\b.*"))return new Intent("topic",content);return new Intent("teach",content);}return null;
 }
  static PageCrawl.Saver saver(final Context c){return new PageCrawl.Saver(){public String save(PageReader.Document d)throws Exception{String receipt=rememberReader(c,d.title,d.reader(),d.url,"web");try{CodeBank.add(c,d.code,d.url);}catch(Exception ignored){}return receipt;}};}
 static PageLoader loader(final Context c){return new PageLoader(){public PageReader.Document load(String url)throws Exception{return PageReader.fetch(c,url);}};}
 /** In the installed app with continuous learning on, only the first page is read in the chat; the rest goes to the background job. */
 static boolean background(Context c){return !(c instanceof NotebookDisk.Provider)&&LearningLoop.enabled(c);}
 static String crawl(final Context c,Intent p,PageLoader pages)throws Exception{final int before=CodeBank.rows(c).length();PageCrawl.Plan plan=PageCrawl.plan(p.text,p.url);boolean open=PageCrawl.wording(p.text).matches(".*(?:otros sitios|otras paginas web|otros dominios|cualquier sitio|sali(?:endo)? del sitio|fuera del sitio|toda la (?:web|internet|red)|todo internet).*");if(open&&!background(c))return "Seguir enlaces hacia otros sitios trabaja en segundo plano con el aprendizaje continuo, que está pausado. Decí «activá el aprendizaje continuo» y pedímelo de nuevo, o pedí sólo los subenlaces del mismo sitio.";if(background(c)){try{String text=CrawlJob.start(c,plan,pages,saver(c),open);LearningLoop.wake(c);return text;}catch(IllegalStateException busy){return busy.getMessage();}}PageCrawl.Report report=PageCrawl.run(plan,pages,saver(c));String text=PageCrawl.describe(plan,report);int found=CodeBank.rows(c).length()-before;return found>0?text+"\nAdemás separé "+found+(found==1?" ejemplo":" ejemplos")+" de Java de esas páginas. Decí «ejemplos de Java» para verlos y probarlos con el compilador.":text;}
 interface PageLoader{PageReader.Document load(String url)throws Exception;}
 static final PageLoader PAGES=new PageLoader(){public PageReader.Document load(String url)throws Exception{return PageReader.fetch(url);}};
 static BananaEngine.Result handle(final Context c,String input)throws Exception{return handle(c,input,new PageLoader(){public PageReader.Document load(String url)throws Exception{return PageReader.fetch(c,url);}});}
 static BananaEngine.Result handle(Context c,String input,PageLoader pages)throws Exception{Intent p;try{p=parse(input);}catch(IllegalArgumentException e){return MobileCore.say(c,e.getMessage(),"aprendizaje_local");}if(p==null)return null;JavaChat.owner=Thread.currentThread();try{String text;if(p.kind.equals("file"))return MobileCore.say(c,"Elegí un archivo TXT o Markdown UTF-8. Lo guardaré por fragmentos sin cargarlo completo en el chat.","knowledge_import_text");else if(p.kind.equals("export")){NotebookArchive.export(c);return MobileCore.say(c,"Preparé un respaldo completo de los documentos y su índice de fuentes para guardarlo.","knowledge_export");}else if(p.kind.equals("import"))return MobileCore.say(c,"Elegí el respaldo ZIP de conocimiento. Validaré sus documentos antes de incorporarlos; conservaré las fuentes privadas con el mismo identificador.","knowledge_import");else if(p.kind.equals("vocabulary"))text=NotebookDisk.of(c).vocabulary();else if(p.kind.equals("status"))text=NotebookDisk.of(c).summary();else if(p.kind.equals("last")){JSONArray rows=NotebookDisk.of(c).latest();if(rows.length()==0)text="Todavía no hay una fuente reciente en esta biblioteca.";else{JSONObject row=rows.getJSONObject(0);StringBuilder excerpts=new StringBuilder("Fragmentos iniciales de la última fuente guardada:\n");String[] parts=chunks(row.getString("text"));for(int i=0;i<Math.min(3,parts.length);i++)excerpts.append(parts[i]).append("\n");text=excerpts+"Fuente: "+row.getString("source")+". Es extracción, no verificación externa.";}}else if(p.kind.equals("clear")){NotebookDisk.of(c).clear();try{ReadingTraining.forgot(c);LearningLoop.forget(c);LectorTraining.forget(c);FollowUp.forget(c);text="Borré documentos, ejercicios y cola de entrenamiento. Los pesos ya entrenados se conservan; borrar texto no desentrena el modelo.";}catch(Exception cleanup){text="Borré los documentos; faltó limpiar parte del progreso o los ejercicios: "+AndroidRepair.summary(cleanup);}}else if(p.kind.equals("crawl_on")){PageCrawl.prefs(c).edit().putBoolean("always",true).commit();text="Desde ahora, cuando me pases un enlace también leo sus subenlaces del mismo sitio: "+PageCrawl.DEFAULT_DEPTH+" niveles y hasta "+PageCrawl.DEFAULT_PAGES+" páginas por recorrido, salvo que indiques otros números. Para volver a una sola página decí «no leas los subenlaces».";}else if(p.kind.equals("crawl_off")){PageCrawl.prefs(c).edit().putBoolean("always",false).commit();text="Listo: leo sólo la página que me pases. Para un recorrido puntual decí «leé los subenlaces» junto al enlace.";}else if(p.kind.equals("crawl_last")){JSONArray rows=NotebookDisk.of(c).latest();if(rows.length()==0||!rows.getJSONObject(0).optString("origin").equals("web"))text="No tengo una página web reciente de la cual seguir enlaces. Pasame el enlace junto con «leé los subenlaces».";else{p.url=rows.getJSONObject(0).getString("source");p.kind="web";text=crawl(c,p,pages);}}else if(p.kind.equals("library_room"))text=NotebookDisk.of(c).room()+"\nCuando se llena, no borro nada por mi cuenta: las lecturas nuevas se rechazan. Para hacer lugar decí, por ejemplo, «borrá las 50 páginas más viejas». Sólo se borran páginas leídas de la web; tus aportes, archivos y correcciones quedan.";else if(p.kind.equals("library_trim")){int n=Integer.parseInt(p.text);if(n<1||n>1000)text="Decime un número entre 1 y 1000.";else{List<NotebookDisk.Doc> gone=NotebookDisk.of(c).forgetOldestWeb(n);StringBuilder t=new StringBuilder(gone.isEmpty()?"No había páginas de la web para borrar.":"Borré "+gone.size()+(gone.size()==1?" página":" páginas")+" de la web, las más viejas:");for(int i=0;i<Math.min(5,gone.size());i++)t.append("\n· ").append(gone.get(i).title);if(gone.size()>5)t.append("\n· …y ").append(gone.size()-5).append(" más.");text=t+"\n"+NotebookDisk.of(c).room()+"\nLo que el modelo ya entrenó con ellas no se desentrena.";}}else if(p.kind.equals("conflicts")){JavaChat.phase("Comparando lo que dicen las fuentes sobre los mismos términos…");text=SourceConflicts.report(c);}else if(p.kind.equals("reader_status"))text=LectorTraining.summary(c);else if(p.kind.equals("real_good")||p.kind.equals("real_bad")){boolean good=p.kind.equals("real_good");/* The verdict goes to whichever spoke last: the chat bank or the reader. */String chat=ChatBank.lastTime(c)>RealExam.lastTime(c)?ChatBank.mark(c,good):null;text=chat!=null?chat:RealExam.mark(c,good);}else if(p.kind.equals("self_tune")){JavaChat.phase("Probando niveles de seguridad con tus preguntas calificadas…");final Context context=c;text=SelfTune.tune(c,new SelfTune.Judge(){public Lector.Found best(String question)throws Exception{return Lector.read(Lector.load(context),NotebookDisk.of(context).selected(question),question,0);}});}else if(p.kind.equals("self_reset"))text=SelfTune.reset(c);else if(p.kind.equals("real_exam")){JavaChat.phase("Repitiendo tus preguntas calificadas…");final Context context=c;text=RealExam.run(c,new RealExam.Reader(){public String sentence(String question)throws Exception{Lector.Found f=Lector.read(Lector.load(context),NotebookDisk.of(context).selected(question),question);return f==null?null:f.sentence;}});if(text.startsWith("Examen con tus preguntas"))try{text+="\n\n"+SelfTune.tune(c,new SelfTune.Judge(){public Lector.Found best(String question)throws Exception{return Lector.read(Lector.load(context),NotebookDisk.of(context).selected(question),question,0);}});}catch(Exception ignored){}}else if(p.kind.equals("reader_exam")){JavaChat.phase("Tomando un examen con preguntas de tus lecturas…");text=LectorExam.now(c);}else if(p.kind.equals("self_check")){JavaChat.phase("Revisando las partes de Banana…");text=SelfCheck.run(c);}else if(p.kind.equals("reader_grow")){JavaChat.phase("Agregando una capa al lector y comprobando que no cambie sus respuestas…");text=LectorTraining.growNow(c);}else if(p.kind.equals("coach"))text="Puedo aprender contenido que me enseñes y retener páginas públicas. Decime qué tema querés que aprenda o pasame el texto/enlace. También puedo entrenar el Transformer si me pedís mejorar Chat más a fondo, pero pocos ejemplos no garantizan inteligencia general. No cambié pesos ni código con este pedido impreciso.";else if(p.kind.equals("teach"))text=remember(c,"",p.text,"user","user");else if(p.kind.equals("topic")){JavaChat.phase("Consultando una fuente sobre "+p.text+"…");String topic=Knowledge.normalize(p.text);WebMemory.lookup(c,topic);JSONObject row=WebMemory.forTopic(c,topic);if(row==null)throw new IOException("No encontré una fuente que pudiera guardar");text=remember(c,row.getString("title"),row.getString("text"),row.getString("source"),"web");}else{JavaChat.phase("Leyendo la página pública y guardando su texto…");if(p.crawl||PageCrawl.always(c))text=crawl(c,p,pages);else try(PageReader.Document d=pages.load(p.url)){text=rememberReader(c,d.title,d.reader(),d.url,"web");int found=0;try{found=CodeBank.add(c,d.code,d.url);}catch(Exception ignored){}if(found>0)text+="\nSeparé "+found+(found==1?" ejemplo":" ejemplos")+" de Java de la página. Decí «ejemplos de Java» para verlos y probarlos con el compilador.";int more=PageCrawl.sameSite(d);if(more>0)text+="\nEsta página enlaza "+more+(more==1?" subenlace":" subenlaces")+" del mismo sitio. Si querés que también los lea, decí «leé los subenlaces».";}}return MobileCore.say(c,text,"aprendizaje_local");}catch(Exception e){return MobileCore.say(c,p.kind.equals("web")?PageReader.failure(p.url,e):"No pude incorporar conocimiento nuevo: "+AndroidRepair.summary(e),"aprendizaje_local");}finally{JavaChat.owner=null;JavaChat.progress="";}}
}
